// Domain service — pure domain logic, no infrastructure
struct MoneyTransferService {
    func transfer(
        amount: Money,
        from source: Account,
        to destination: Account
    ) throws -> (debited: Account, credited: Account) {
        let debited = try source.debit(amount)
        let credited = destination.credit(amount)
        return (debited, credited)
    }
}

// Application service — orchestration + infrastructure
final class TransferFundsUseCase {
    private let accountRepository: AccountRepository
    private let transferService: MoneyTransferService
    private let eventPublisher: DomainEventPublisher

    func execute(command: TransferFundsCommand) async throws {
        // Load aggregates (infrastructure concern)
        let source = try await accountRepository.findById(command.sourceId)
        let destination = try await accountRepository.findById(command.destinationId)

        // Domain logic (delegate to domain service)
        let (debited, credited) = try transferService.transfer(
            amount: command.amount, from: source, to: destination
        )

        // Persist (infrastructure concern)
        try await accountRepository.save(debited)
        try await accountRepository.save(credited)

        // Publish event (application concern)
        await eventPublisher.publish(FundsTransferred(command: command))
    }
}

// Stateless domain service — dependencies injected, no mutable state
struct ShippingCalculator {
    // Injected at init — not mutated between calls
    private let feePolicy: ShippingFeePolicy

    init(feePolicy: ShippingFeePolicy) {
        self.feePolicy = feePolicy
    }

    func calculateShipping(for order: Order, from warehouse: Warehouse) -> Money {
        let distance = warehouse.location.distance(to: order.deliveryAddress)
        let weight = order.totalWeight()
        return feePolicy.fee(distance: distance, weight: weight)
    }
}

// ANTI-PATTERN: Anemic domain model with all logic in services
struct Account {
    var id: AccountID
    var balance: Money      // just data, no behavior
    var status: AccountStatus
}

// A "service" that handles all the Account logic
// This is procedural code masquerading as OOP
struct AccountService {
    func debit(_ account: inout Account, amount: Money) throws {
        guard account.status == .active else { throw AccountError.inactive }
        guard account.balance >= amount else { throw AccountError.insufficientFunds }
        account.balance -= amount  // manipulating another object's internals
    }

    func credit(_ account: inout Account, amount: Money) {
        account.balance += amount
    }
}

// CORRECT: Rich domain model — behavior on the entity
struct Account {
    private(set) var id: AccountID
    private(set) var balance: Money
    private(set) var status: AccountStatus

    // Debit logic belongs HERE — it operates on Account's own invariants
    mutating func debit(_ amount: Money) throws {
        guard status == .active else { throw AccountError.inactive }
        guard balance >= amount else { throw AccountError.insufficientFunds }
        balance -= amount
    }

    mutating func credit(_ amount: Money) {
        balance += amount
    }
}

// Domain service only for the cross-aggregate operation
struct MoneyTransferService {
    func transfer(
        amount: Money,
        from source: inout Account,
        to destination: inout Account
    ) throws {
        try source.debit(amount)       // delegate to entity
        destination.credit(amount)     // delegate to entity
    }
}

// Domain objects
struct Money: Equatable {
    let amount: Decimal
    let currency: Currency

    static func >= (lhs: Money, rhs: Money) -> Bool {
        precondition(lhs.currency == rhs.currency)
        return lhs.amount >= rhs.amount
    }

    static func - (lhs: Money, rhs: Money) -> Money {
        precondition(lhs.currency == rhs.currency)
        return Money(amount: lhs.amount - rhs.amount, currency: lhs.currency)
    }

    static func + (lhs: Money, rhs: Money) -> Money {
        precondition(lhs.currency == rhs.currency)
        return Money(amount: lhs.amount + rhs.amount, currency: lhs.currency)
    }
}

enum TransferError: Error {
    case insufficientFunds
    case accountInactive
    case currencyMismatch
}

struct Account {
    let id: AccountID
    private(set) var balance: Money
    private(set) var status: AccountStatus

    mutating func debit(_ amount: Money) throws {
        guard status == .active else { throw TransferError.accountInactive }
        guard balance >= amount else { throw TransferError.insufficientFunds }
        guard balance.currency == amount.currency else { throw TransferError.currencyMismatch }
        balance = balance - amount
    }

    mutating func credit(_ amount: Money) throws {
        guard status == .active else { throw TransferError.accountInactive }
        guard balance.currency == amount.currency else { throw TransferError.currencyMismatch }
        balance = balance + amount
    }
}

// Domain service — pure, stateless, spans two aggregates
struct MoneyTransferService {
    func transfer(
        amount: Money,
        from source: inout Account,
        to destination: inout Account
    ) throws {
        // Delegates invariant enforcement to the entities
        try source.debit(amount)
        try destination.credit(amount)
    }
}

struct OrderFulfillmentService {
    private let inventoryService: InventoryReservationService
    private let shippingCalculator: ShippingCalculator

    init(
        inventoryService: InventoryReservationService,
        shippingCalculator: ShippingCalculator
    ) {
        self.inventoryService = inventoryService
        self.shippingCalculator = shippingCalculator
    }

    func fulfill(
        order: Order,
        warehouse: Warehouse
    ) throws -> FulfillmentPlan {
        // Compose domain services — both are pure
        let reservation = try inventoryService.reserve(
            items: order.lineItems, from: warehouse
        )
        let shippingCost = shippingCalculator.calculateShipping(
            for: order, from: warehouse
        )
        return FulfillmentPlan(
            reservation: reservation,
            shippingCost: shippingCost
        )
    }
}

// Tests for MoneyTransferService — no mocks, no framework setup
import Testing

@Suite("MoneyTransferService")
struct MoneyTransferServiceTests {
    let service = MoneyTransferService()

    @Test("transfers amount from source to destination")
    func transfersAmount() throws {
        var source = Account(
            id: AccountID("src-1"),
            balance: Money(amount: 1000, currency: .usd),
            status: .active
        )
        var destination = Account(
            id: AccountID("dst-1"),
            balance: Money(amount: 200, currency: .usd),
            status: .active
        )

        try service.transfer(
            amount: Money(amount: 300, currency: .usd),
            from: &source,
            to: &destination
        )

        #expect(source.balance == Money(amount: 700, currency: .usd))
        #expect(destination.balance == Money(amount: 500, currency: .usd))
    }

    @Test("throws insufficientFunds when source balance is too low")
    func throwsOnInsufficientFunds() {
        var source = Account(
            id: AccountID("src-2"),
            balance: Money(amount: 50, currency: .usd),
            status: .active
        )
        var destination = Account(
            id: AccountID("dst-2"),
            balance: Money(amount: 0, currency: .usd),
            status: .active
        )

        #expect(throws: TransferError.insufficientFunds) {
            try service.transfer(
                amount: Money(amount: 300, currency: .usd),
                from: &source,
                to: &destination
            )
        }
    }

    @Test("throws accountInactive when source account is inactive")
    func throwsOnInactiveSource() {
        var source = Account(
            id: AccountID("src-3"),
            balance: Money(amount: 1000, currency: .usd),
            status: .suspended
        )
        var destination = Account(
            id: AccountID("dst-3"),
            balance: Money(amount: 0, currency: .usd),
            status: .active
        )

        #expect(throws: TransferError.accountInactive) {
            try service.transfer(
                amount: Money(amount: 100, currency: .usd),
                from: &source,
                to: &destination
            )
        }
    }
}

struct ShippingCalculator {
    private let feePolicy: CarrierFeePolicy

    init(feePolicy: CarrierFeePolicy) {
        self.feePolicy = feePolicy
    }

    // Pure computation — no mutation, no I/O
    func calculateShipping(
        for order: Order,
        from warehouse: Warehouse
    ) -> Money {
        let weight = order.totalWeight()
        let distance = warehouse.location.distanceTo(order.deliveryAddress)
        let carrier = feePolicy.preferredCarrier(weight: weight, distance: distance)
        let baseRate = carrier.baseRate(for: distance)
        let weightSurcharge = feePolicy.weightSurcharge(weight: weight)
        return Money(
            amount: baseRate + weightSurcharge,
            currency: feePolicy.billingCurrency
        )
    }
}

// Domain layer: defines the contract
protocol TaxCalculationService {
    func calculateTax(on price: Money, for address: PostalAddress) -> Money
}

// Domain layer: uses the protocol — stays pure
struct OrderPricingService {
    private let taxService: TaxCalculationService

    init(taxService: TaxCalculationService) {
        self.taxService = taxService
    }

    func totalPrice(for order: Order) -> Money {
        let subtotal = order.subtotal()
        let tax = taxService.calculateTax(on: subtotal, for: order.deliveryAddress)
        return subtotal + tax
    }
}

